func is_basic_playable(card_suit: String, card_rank: int, top_suit: String, top_rank: int) -> bool:
    var same_suit: bool = (card_suit == top_suit)
    var same_rank: bool = (card_rank == top_rank)
    var is_wild: bool = (card_rank == 14 or card_rank == 15)
    return same_suit or same_rank or is_wild

func describe_card_role(rank: int) -> String:
    if rank == 2 or rank == 3 or rank == 15:
        return "Penalty Card"
    elif rank == 11:
        return "Jump Card (Skip next player)"
    elif rank == 13:
        return "Kickback Card (Reverse direction)"
    elif rank == 12 or rank == 8:
        return "Question Card (Must pair with Answer)"
    else:
        return "Answer Card"

