func deal_opening_hands(hands: Array, deck: Array, cards_per_player: int = 4) -> void:
    for player_idx in range(hands.size()):
        for _i in range(cards_per_player):
            if not deck.is_empty():
                hands[player_idx].append(deck.pop_back())

func draw_from_deck(deck: Array, count: int = 1) -> Array:
    var drawn: Array = []
    for _i in range(count):
        if not deck.is_empty():
            drawn.append(deck.pop_back())
    return drawn

func is_penalty_rank(rank: int) -> bool:
    return rank == 2 or rank == 3 or rank == 15

